// The demo's one video's bytes, as base64: four seconds of a test card with its frame counter
// and a quiet tone, as WebM (VP9 and Opus), 640 × 360. Made with
//   ffmpeg -f lavfi -i testsrc2=size=640x360:rate=30 -f lavfi -i sine=frequency=330:duration=4 -t 4 \
//     -c:v libvpx-vp9 -b:v 150k -af volume=0.04 -c:a libopus -b:a 12k sample.webm
// Only `clip.ts` loads this, when something plays the video, so it stays out of the demo's
// first load.

export const bytes = (): Uint8Array<ArrayBuffer> =>
  Uint8Array.from(atob(data), (char) => char.charCodeAt(0))

const data =
  ""
